<?php
declare(strict_types=1);
namespace VV;
defined('VV_ROOT') || exit;
final class FormsAdmin {
    private static function start(string $op): string{return '<form method="post">'.\csrf_field().'<input type="hidden" name="action" value="plugin.save"><input type="hidden" name="op" value="'.\e($op).'">';}
    private static function password(): string{return '<label>'.\e(\t('Mot de passe actuel','Current password')).'<input name="current_password" type="password" required autocomplete="current-password"></label>';}
    private static function defaults(): array {
        $fields=[];foreach([['name','text','Nom / Name',true],['email','email','E-mail',true],['phone','tel','Téléphone / Phone',false],['message','textarea','Message',true]] as [$key,$type,$label,$required])$fields[]=['key'=>$key,'type'=>$type,'label'=>$label,'required'=>$required,'help'=>'','choices'=>[]];
        return ['id'=>'contact','name'=>'Contact','published'=>false,'version'=>0,'retention_days'=>90,'privacy'=>\t('Les informations servent à répondre à votre demande. Contactez le propriétaire pour toute question sur vos données.','Details are used to answer your request. Contact the owner with questions about your data.'),'confirmation'=>\t('Merci, votre demande a été enregistrée.','Thank you, your request has been saved.'),'fields'=>$fields];
    }
    public static function save(App $app,array $p): void {
        Security::requireOwner($app->store);$op=\val($p,'op');
        if(in_array($op,['settings','export-json','export-csv','purge','delete-row','delete-form','retry','notifications'],true))Security::reauth($app->store,\val($p,'current_password'));
        if(in_array($op,['export-json','export-csv'],true)){self::export($app,$op);exit;}
        if($op==='notifications'){Forms::drain($app);return;}
        if($op==='purge'){if(\val($p,'confirm')!=='PURGE')throw new Failure('Saisissez PURGE / Enter PURGE.');Forms::purgeExpired($app);return;}
        $app->store->change(function(&$s)use($p,$op){
            $d=Forms::data($s);$id=\val($p,'id');
            if($op==='settings'){$enabled=isset($p['notify']);$d['settings']=['notify'=>$enabled,'to'=>Forms::email(\val($p,'to'),$enabled),'from'=>Forms::email(\val($p,'from'),$enabled)];}
            elseif($op==='definition'){
                $old=$d['forms'][$id]??null;if(($old['version']??0)!==(int)\val($p,'version'))throw new Failure('Formulaire modifié / Form changed.',409);
                if(!$old&&count($d['forms'])>=Forms::MAX_FORMS)throw new Failure('Forms: 10 formulaires / forms.',413);$fields=[];
                for($n=0;$n<Forms::MAX_FIELDS;$n++){$label=Forms::text(\val($p,'field_'.$n.'_label'),100);if($label==='')continue;$choices=trim(\val($p,'field_'.$n.'_choices'));
                    $fields[]=['key'=>\val($p,'field_'.$n.'_key','field_'.($n+1)),'type'=>\val($p,'field_'.$n.'_type','text'),'label'=>$label,'help'=>\val($p,'field_'.$n.'_help'),'required'=>isset($p['field_'.$n.'_required']),'choices'=>$choices===''?[]:preg_split('/\r?\n/',$choices),'sort'=>(int)\val($p,'field_'.$n.'_order',(string)$n)];}
                usort($fields,fn($a,$b)=>$a['sort']<=>$b['sort']);foreach($fields as &$field)unset($field['sort']);unset($field);
                $days=\val($p,'retention_days');if(!preg_match('/^\d{1,4}$/D',$days))throw new Failure('Conservation : 1–3650 jours / Retention: 1–3650 days.');
                $d['forms'][$id]=Forms::definition(['id'=>$id,'name'=>\val($p,'name'),'published'=>isset($p['published']),'version'=>($old['version']??0)+1,'retention_days'=>(int)$days,'privacy'=>\val($p,'privacy'),'confirmation'=>\val($p,'confirmation'),'fields'=>$fields]);
            }elseif($op==='delete-form'){
                if(\val($p,'confirm')!=='DELETE')throw new Failure('Saisissez DELETE / Enter DELETE.');if(!isset($d['forms'][$id]))throw new Failure('Formulaire absent / Form absent.',404);unset($d['forms'][$id]);
            }elseif(in_array($op,['status','delete-row','retry'],true)){
                $r=$d['rows'][$id]??null;if(!$r)throw new Failure('Demande absente / Request absent.',404);if($r['version']!==(int)\val($p,'version'))throw new Failure('Demande modifiée / Request changed.',409);
                if($op==='delete-row')unset($d['rows'][$id]);elseif($op==='retry'){
                    if(\val($p,'confirm')!=='RETRY'||!in_array($r['notification']['status'],['failed','unknown'],true)||$r['notification']['attempts']>=100||!$d['settings']['notify'])throw new Failure('Reprise refusée / Retry refused.');
                    $d['rows'][$id]['notification']['status']='pending';$d['rows'][$id]['notification']['to']=$d['settings']['to'];$d['rows'][$id]['notification']['from']=$d['settings']['from'];$d['rows'][$id]['notification']['lease']='';$d['rows'][$id]['version']++;
                }else{$status=\val($p,'status');if(!in_array($status,['new','read','handled','spam'],true))throw new Failure('Statut invalide / Invalid status.');$d['rows'][$id]['status']=$status;$d['rows'][$id]['version']++;}
            }else throw new Failure('Forms: action inconnue / unknown action.');
            Forms::put($s,$d);Store::log($s,'forms_'.$op,in_array($op,['status','delete-row','retry','delete-form'],true)?$id:'');
        });
    }
    private static function export(App $app,string $op): void {
        $d=Forms::data($app->store->read());header('Cache-Control: private, no-store');
        if($op==='export-json'){header('Content-Type: application/json; charset=utf-8');header('Content-Disposition: attachment; filename="voilavoila-forms.json"');echo json_encode($d,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);return;}
        header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="voilavoila-forms.csv"');$out=fopen('php://output','wb');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['request_id','form','created_utc','status','notification','field','label','value'],',','"','');
        foreach($d['rows'] as $r)foreach($r['form']['fields'] as $f)fputcsv($out,array_map([Forms::class,'csvCell'],[$r['id'],$r['form']['name'],gmdate('c',$r['created']),$r['status'],$r['notification']['status'],$f['key'],$f['label'],$r['values'][$f['key']]]),',','"','');fclose($out);
    }
    public static function render(App $app): void {
        $d=Forms::data($app->state);$editing=\val($_GET,'form');$f=$d['forms'][$editing]??self::defaults();$isNew=!isset($d['forms'][$editing]);$keys=array_fill_keys(array_column($f['fields'],'key'),true);$blank=[];
        for($n=count($f['fields']);$n<Forms::MAX_FIELDS;$n++){$k=$n+1;while(isset($keys['field_'.$k]))$k++;$blank[$n]='field_'.$k;$keys['field_'.$k]=true;}
        $labels=['all'=>\t('Tous','All'),'new'=>\t('Nouveau','New'),'read'=>\t('Lu','Read'),'handled'=>\t('Traité','Handled'),'spam'=>\t('Indésirable','Spam')];
        ?>
<section class="panel"><h2><?=\e(\t('Formulaires et boîte privée','Forms and private inbox'))?></h2><p><?=\e(\t('Ajoutez le tag publié dans une page ou un article public. Les demandes restent privées ; JavaScript est facultatif.','Place the published tag in a public page or post. Requests remain private; JavaScript is optional.'))?></p><p><?=count($d['forms'])?> / 10 · <?=count($d['rows'])?> / 500 · 2 Mio Forms / 8 Mio CMS</p><div class="button-row"><a class="button secondary" href="<?=\e(\admin_url('plugin-forms',['form'=>'new']))?>"><?=\e(\t('Nouveau formulaire','New form'))?></a><?php foreach($d['forms'] as $form):?><a class="button secondary" href="<?=\e(\admin_url('plugin-forms',['form'=>$form['id']]))?>"><?=\e($form['name'])?> <code>[form-<?=\e($form['id'])?>]</code></a><?php endforeach;?></div></section>
<details class="panel" <?=($editing!==''||!$d['forms'])?'open':''?>><summary><?=\e($isNew?\t('Créer un formulaire','Create form'):\t('Modifier le formulaire','Edit form'))?></summary><?=self::start('definition')?><input type="hidden" name="version" value="<?=$f['version']?>"><label><?=\e(\t('Identifiant du tag','Tag identifier'))?><input name="id" maxlength="25" pattern="[a-z][a-z0-9-]{0,24}" value="<?=\e($f['id'])?>" required <?=$isNew?'':'readonly'?>></label><label><?=\e(\t('Titre','Title'))?><input name="name" value="<?=\e($f['name'])?>" maxlength="100" required></label><label class="checkbox"><input type="checkbox" name="published" <?=$f['published']?'checked':''?>><?=\e(\t('Publier le formulaire','Publish form'))?></label><label><?=\e(\t('Conservation des nouvelles demandes (jours)','New request retention (days)'))?><input type="number" name="retention_days" min="1" max="3650" value="<?=$f['retention_days']?>" required></label><label><?=\e(\t('Information sur les données','Data notice'))?><textarea name="privacy" maxlength="1500" required><?=\e($f['privacy'])?></textarea></label><label><?=\e(\t('Confirmation','Confirmation'))?><textarea name="confirmation" maxlength="500" required><?=\e($f['confirmation'])?></textarea></label><p><?=\e(\t('Un libellé vide retire le champ. Modifiez les nombres pour l’ordre ; un choix par ligne pour les listes.','An empty label removes a field. Order by numbers; one select choice per line.'))?></p>
<?php for($n=0;$n<Forms::MAX_FIELDS;$n++):$field=$f['fields'][$n]??['key'=>$blank[$n],'label'=>'','type'=>'text','help'=>'','required'=>false,'choices'=>[]];?>
<details class="vv-field-editor" <?=$n<count($f['fields'])?'open':''?>><summary><?=\e(\t('Champ','Field'))?> <?=$n+1?> · <?=\e($field['label'])?></summary><input type="hidden" name="field_<?=$n?>_key" value="<?=\e($field['key'])?>"><div class="form-grid"><label><?=\e(\t('Libellé','Label'))?><input name="field_<?=$n?>_label" maxlength="100" value="<?=\e($field['label'])?>"></label><label><?=\e(\t('Ordre','Order'))?><input type="number" name="field_<?=$n?>_order" value="<?=$n?>" min="0" max="99"></label><label>Type<select name="field_<?=$n?>_type"><?php foreach(['text','email','tel','textarea','select','checkbox'] as $type):?><option <?=$type===$field['type']?'selected':''?>><?=$type?></option><?php endforeach;?></select></label><label class="checkbox"><input type="checkbox" name="field_<?=$n?>_required" <?=$field['required']?'checked':''?>><?=\e(\t('Obligatoire','Required'))?></label></div><label><?=\e(\t('Aide','Help'))?><input name="field_<?=$n?>_help" maxlength="250" value="<?=\e($field['help'])?>"></label><label><?=\e(\t('Choix (30 maximum)','Choices (up to 30)'))?><textarea name="field_<?=$n?>_choices" maxlength="3030"><?=\e(implode("\n",$field['choices']))?></textarea></label></details><?php endfor;?><button class="button primary"><?=\e(\t('Enregistrer le formulaire','Save form'))?></button></form>
<?php if(!$isNew):?><details><summary><?=\e(\t('Retirer le formulaire (demandes conservées)','Remove form (retain requests)'))?></summary><?=self::start('delete-form')?><input type="hidden" name="id" value="<?=\e($f['id'])?>"><label>DELETE<input name="confirm" pattern="DELETE" required></label><?=self::password()?><button class="button danger">DELETE</button></form></details><?php endif;?></details>
<?php $status=\val($_GET,'status','all');$query=Content::text(\val($_GET,'q'),100);$filter=\val($_GET,'filter_form');$rows=array_values(array_filter($d['rows'],fn($r)=>($status==='all'||$r['status']===$status)&&($filter===''||$r['form']['id']===$filter)&&($query===''||mb_stripos(implode(' ',$r['values']),$query)!==false)));usort($rows,fn($a,$b)=>$b['created']<=>$a['created']?:strcmp($b['id'],$a['id']));$page=max(1,min(25,(int)\val($_GET,'page','1')));$selected=$d['rows'][\val($_GET,'request')]??null;?>
<section class="panel"><h2><?=\e(\t('Boîte de réception','Inbox'))?></h2><form method="get" class="filter-bar"><input type="hidden" name="view" value="plugin-forms"><input type="hidden" name="lang" value="<?=\e(\lang())?>"><label><?=\e(\t('Recherche privée','Private search'))?><input name="q" maxlength="100" value="<?=\e($query)?>"></label><label><?=\e(\t('Statut','Status'))?><select name="status"><?php foreach($labels as $key=>$label):?><option value="<?=$key?>" <?=$status===$key?'selected':''?>><?=\e($label)?></option><?php endforeach;?></select></label><label><?=\e(\t('Identifiant du formulaire','Form identifier'))?><input name="filter_form" value="<?=\e($filter)?>"></label><button class="button secondary"><?=\e(\t('Filtrer','Filter'))?></button></form><p><?=count($rows)?> <?=\e(\t('demandes','requests'))?></p><div class="table-scroll"><table><thead><tr><th>Date / Form</th><th><?=\e(\t('Statut','Status'))?></th><th>Notification</th><th><?=\e(\t('Ouvrir','Open'))?></th></tr></thead><tbody><?php foreach(array_slice($rows,($page-1)*20,20) as $r):?><tr><td><?=\e(gmdate('Y-m-d H:i',$r['created']).' · '.$r['form']['name'])?></td><td><?=\e($labels[$r['status']])?></td><td><?=\e($r['notification']['status'])?></td><td><a href="<?=\e(\admin_url('plugin-forms',['request'=>$r['id']]))?>"><?=\e(substr($r['id'],0,8))?></a></td></tr><?php endforeach;?></tbody></table></div><div class="button-row"><?php foreach([-1,1] as $delta):$num=$page+$delta;if($num<1||$delta===1&&count($rows)<=$page*20)continue;?><a class="button secondary" href="<?=\e(\admin_url('plugin-forms',['page'=>$num,'status'=>$status,'q'=>$query,'filter_form'=>$filter]))?>"><?=\e($delta===1?\t('Suivant','Next'):\t('Précédent','Previous'))?></a><?php endforeach;?></div></section>
<?php if($selected):$r=$selected;?><section class="panel"><h2><?=\e($r['form']['name'].' · '.$r['id'])?></h2><dl><?php foreach($r['form']['fields'] as $field):?><dt><strong><?=\e($field['label'])?></strong></dt><dd><?=nl2br(\e($r['values'][$field['key']]))?></dd><?php endforeach;?></dl><p><?=\e(\t('Expiration','Expiry').': '.gmdate('c',$r['expires']))?></p><?=self::start('status')?><input type="hidden" name="id" value="<?=\e($r['id'])?>"><input type="hidden" name="version" value="<?=$r['version']?>"><select name="status"><?php foreach(['new','read','handled','spam'] as $key):?><option value="<?=$key?>" <?=$r['status']===$key?'selected':''?>><?=\e($labels[$key])?></option><?php endforeach;?></select><button class="button primary"><?=\e(\t('Mettre à jour','Update'))?></button></form><details><summary><?=\e(\t('Supprimer définitivement','Delete permanently'))?></summary><?=self::start('delete-row')?><input type="hidden" name="id" value="<?=\e($r['id'])?>"><input type="hidden" name="version" value="<?=$r['version']?>"><?=self::password()?><button class="button danger">DELETE</button></form></details><?php if(in_array($r['notification']['status'],['failed','unknown'],true)):?><details><summary><?=\e(\t('Reprendre la notification','Retry notification'))?></summary><p><?=\e(\t('Un résultat inconnu peut avoir envoyé l’e-mail. Une reprise explicite peut créer un doublon.','An unknown outcome may already have sent mail. An explicit retry can duplicate it.'))?></p><?=self::start('retry')?><input type="hidden" name="id" value="<?=\e($r['id'])?>"><input type="hidden" name="version" value="<?=$r['version']?>"><label>RETRY<input name="confirm" pattern="RETRY" required></label><?=self::password()?><button class="button secondary">RETRY</button></form></details><?php endif;?></section><?php endif;?>
<section class="panel"><h2><?=\e(\t('Notifications différées','Deferred notifications'))?></h2><p><?=\e(\t('accepted signifie accepté pour acheminement, pas livré. Les échecs et résultats inconnus ne sont pas réessayés automatiquement.','accepted means accepted by transport, not delivered. Failed/unknown outcomes are never retried automatically.'))?></p><?=self::start('settings')?><label class="checkbox"><input type="checkbox" name="notify" <?=$d['settings']['notify']?'checked':''?>><?=\e(\t('Notifier les nouvelles demandes avec mail() PHP','Notify new requests using PHP mail()'))?></label><label><?=\e(\t('Destinataire propriétaire','Owner recipient'))?><input name="to" type="email" maxlength="254" value="<?=\e($d['settings']['to'])?>"></label><label><?=\e(\t('Expéditeur autorisé par l’hébergeur','Sender allowed by hosting provider'))?><input name="from" type="email" maxlength="254" value="<?=\e($d['settings']['from'])?>"></label><?=self::password()?><button class="button primary"><?=\e(\t('Enregistrer','Save'))?></button></form><?=self::start('notifications')?><?=self::password()?><button class="button secondary"><?=\e(\t('Traiter jusqu’à 10 notifications','Process up to 10 notifications'))?></button></form><code>php bin/console.php forms:notifications</code></section>
<section class="panel"><h2><?=\e(\t('Export et conservation','Export and retention'))?></h2><p><?=\e(\t('Le JSON conserve les valeurs ; le CSV neutralise les formules. Les sauvegardes incluent Forms. La désactivation conserve les données. Gérez séparément exports et anciennes sauvegardes.','JSON preserves stored values; CSV neutralizes formulas. Backups include Forms. Deactivation retains data. Manage exports and historical backups separately.'))?></p><?php foreach(['export-json'=>'JSON','export-csv'=>'CSV'] as $op=>$label):?><?=self::start($op)?><?=self::password()?><button class="button secondary"><?=\e(\t('Exporter','Export'))?> <?=$label?></button></form><?php endforeach;?><details><summary><?=\e(\t('Purger les demandes expirées','Purge expired requests'))?></summary><?=self::start('purge')?><label>PURGE<input name="confirm" pattern="PURGE" required></label><?=self::password()?><button class="button danger">PURGE</button></form><code>php bin/console.php forms:purge --confirm=PURGE</code></details></section>
<?php }
}
